# SPDX-License-Identifier: MIT
# Trusted observer and setup control for filesystem-boundary fixtures (pane 214).
# Python stdlib only; never imports or runs the candidate.
# Usage:
#   fsobs.py tree PATH...          per entry (sorted walk, no symlink following): relative path, type,
#                                  mode, mtime_ns, nlink, hardlink group, symlink target or content hex
#   fsobs.py exists PATH...        lexists and type of each PATH
#   fsobs.py bytes PATH...         length and hex of each PATH, or absent
#   fsobs.py fill PATH SIZE        create PATH holding SIZE zero bytes
#   fsobs.py symlink TARGET LINK   create LINK -> TARGET
#   fsobs.py mounts JSON           setup control: every [source, fstype, path] is a mount in this namespace
import json, os, stat, sys


def kind(info):
    for test, name in ((stat.S_ISLNK, 'link'), (stat.S_ISDIR, 'dir'), (stat.S_ISREG, 'file'),
                       (stat.S_ISFIFO, 'fifo'), (stat.S_ISCHR, 'chr'), (stat.S_ISBLK, 'blk')):
        if test(info.st_mode):
            return name
    return 'other'


def describe(path, groups):
    info = os.lstat(path)
    key = (info.st_dev, info.st_ino)
    group = groups.setdefault(key, len(groups) + 1) if info.st_nlink > 1 and not stat.S_ISDIR(info.st_mode) else 0
    text = '%s %s %04o mtime=%d nlink=%d hl=%d' % (path, kind(info), stat.S_IMODE(info.st_mode), info.st_mtime_ns,
                                                   info.st_nlink, group)
    if stat.S_ISLNK(info.st_mode):
        text += ' -> ' + os.readlink(path)
    elif stat.S_ISREG(info.st_mode):
        with open(path, 'rb') as handle:
            text += ' data=' + handle.read(64).hex()
    return text


def main():
    command, args = sys.argv[1], sys.argv[2:]
    if command == 'tree':
        groups = {}
        for root in args:
            if not os.path.lexists(root):
                print(root + ' absent')
                continue
            print(describe(root, groups))
            if os.path.isdir(root) and not os.path.islink(root):
                for parent, dirs, files in os.walk(root):
                    dirs.sort()
                    for name in sorted(dirs + files):
                        print(describe(os.path.join(parent, name), groups))
    elif command == 'exists':
        for path in args:
            print('%s %s' % (path, kind(os.lstat(path)) if os.path.lexists(path) else 'absent'))
    elif command == 'bytes':
        for path in args:
            if os.path.lexists(path):
                with open(path, 'rb') as handle:
                    data = handle.read()
                print('%s len=%d hex=%s' % (path, len(data), data.hex()))
            else:
                print(path + ' absent')
    elif command == 'fill':
        with open(args[0], 'wb') as handle:
            handle.write(b'\0' * int(args[1]))
    elif command == 'symlink':
        os.symlink(args[0], args[1])
    elif command == 'mounts':
        table = []
        with open('/proc/self/mountinfo') as handle:
            for line in handle:
                left, right = line.split(' - ', 1)
                fstype, source = right.split()[:2]
                table.append((source, fstype, os.path.realpath(left.split()[4].encode().decode('unicode_escape'))))
        for source, fstype, path in json.loads(args[0]):
            if (source, fstype, os.path.realpath(path)) not in table:
                print('CONTROL-FAILED mount %s %s on %s not present' % (source, fstype, path))
                sys.exit(98)
        print('mount control ok')
    else:
        raise AssertionError(command)


if __name__ == '__main__':
    main()

